const DATA = [{"id": 1, "number": "001", "title": "Mrtvý Tah", "english": "Deadlift", "typ": "Vícekloubový tah; osa (klasická varianta) nebo trap bar (odlišná varianta s jinou polohou těla)", "anatomie": "Hlavní hybatelé: velký hýžďový sval a adduktor velký; podíl hamstringů a kvadricepsů se liší podle varianty a techniky. Stabilizačně pracují vzpřimovače páteře, široký sval zádový, břišní svaly a svaly úchopu.", "biomechanika": "Kyčel a koleno se natahují při zvedání a ohýbají při spouštění. Trup drží páteř stabilní; osa se pohybuje blízko těla.", "vychozi_pozice": "Chodidla přibližně na šířku boků; osa nad středem chodidla. Kyčle dozadu, pokrč kolena tak, abys dosáhla na osu. Zpevni trup, uchop osu a nastav ramena nad nebo mírně před osou podle proporcí.", "provedeni": "Zpevni trup, zatlač chodidly do podlahy a současně natahuj kolena a kyčle. Osa stoupá těsně podél nohou. Nahoře se narovnej bez záklonu. Dolů nejprve pošli kyčle dozadu, potom pokrč kolena a polož osu kontrolovaně.", "spravna_technika": "Osa blízko těla; tlak přes celé chodidlo; páteř drž v přirozené stabilní poloze; pohyb koordinuj v kyčlích a kolenou; nahoře neprohýbej bedra.", "chyby": "Osa ujíždí dopředu — drž ji u nohou. Trhání ze země — začni lehčí vahou a plynule. Ztráta opory chodidel — rozlož tlak přes celé chodidlo. Záklon nahoře — skonči ve vzpřímení, ne v záklonu.", "dychani": "Nadechni se a vytvoř pevný trup před zdvihem; během nejtěžší části plynule vydechuj. Mezi opakováními znovu nastav dech a zpevnění.", "varianty": "Regrese: kettlebell deadlift z vyvýšení nebo tah s lehkou zátěží. Progrese: postupné přidávání zátěže, trap-bar tah nebo pauza těsně nad zemí.", "davkovani": "3 série × 5–8 opakování; pauza 2–3 min; zátěž zvyšuj jen při zachování techniky.", "poporodni_poznamka": "Uč se zvedat zátěž přes kyčle a nohy, ne trhnutím zad. Po porodu začni lehce a sleduj tlak či tíhu v pánevním dnu, únik moči, bolest nebo vyklenování břišní stěny; při potížích sniž zátěž a řeš je s fyzioterapeutkou.", "category": "Nohy a hýždě"}, {"id": 2, "number": "002", "title": "Dřep S Osou", "english": "Barbell Back Squat", "typ": "Vícekloubový tlak dolní poloviny těla; osa na horní části zad", "anatomie": "Kvadricepsy a velký hýžďový sval; pomocně adduktory a hamstringy; stabilizují břišní svaly, vzpřimovače páteře a svaly kolem kyčlí.", "biomechanika": "Současná flexe kyčlí, kolen a kotníků při klesání; extenze při vstávání. Poměr práce kyčlí a kolen ovlivňuje postoj a sklon trupu.", "vychozi_pozice": "Osa bezpečně na horní části zad, ruce symetricky. Chodidla zhruba na šířku ramen, špičky mírně ven podle mobility. Zpevni trup a rozlož váhu přes celé chodidlo.", "provedeni": "Nadechni se a zpevni trup; pokrč kyčle a kolena a klesej mezi chodidla. Kolena sledují směr špiček. Vstaň tlakem přes celé chodidlo, kyčle a hrudník stoupají koordinovaně.", "spravna_technika": "Stabilní chodidla; kolena se pohybují ve směru špiček; páteř zůstává stabilní; hloubka odpovídá mobilitě a kontrole; bez odrazu ze spodní pozice.", "chyby": "Paty se zvedají — uprav postoj nebo hloubku. Kolena padají dovnitř — sniž zátěž a kontroluj osu kolen. Ztráta zpevnění — zkrať rozsah. Předklon či záklon se nekontrolovaně mění — zvol lehčí variantu.", "dychani": "Nádech a zpevnění před sestupem; vydechuj při vstávání. Nezadržuj dech déle, než je nutné pro bezpečné zpevnění.", "varianty": "Regrese: dřep na lavičku, goblet squat nebo dřep s vlastní vahou. Progrese: postupně vyšší zátěž, pauzovaný dřep.", "davkovani": "3 série × 6–10 opakování; pauza 2–3 min.", "poporodni_poznamka": "Po porodu začni variantou, při níž udržíš dech a kontrolu trupu. Při tlaku v pánvi, úniku moči, bolesti nebo vyklenování břicha sniž zátěž či rozsah a vyhledej odborné vedení.", "category": "Nohy a hýždě"}, {"id": 3, "number": "003", "title": "Goblet Squat", "english": "Goblet Squat", "typ": "Vícekloubový dřep; jednoručka nebo kettlebell před hrudníkem", "anatomie": "Kvadricepsy a velký hýžďový sval; pomocně adduktory; stabilizují břišní svaly, vzpřimovače páteře a svaly kolem kyčlí.", "biomechanika": "Flexe kyčlí, kolen a kotníků při sestupu; extenze při návratu. Zátěž vpředu pomáhá udržet vzpřímenější trup.", "vychozi_pozice": "Drž činku blízko hrudníku, lokty směřují dolů. Chodidla přibližně na šířku ramen; špičky mírně ven. Zpevni trup a nastav celé chodidlo na podlahu.", "provedeni": "Současně pokrč kyčle a kolena a klesej mezi chodidla do kontrolované hloubky. Kolena sledují špičky. Zatlač do podlahy a vrať se do stoje.", "spravna_technika": "Činka zůstává u hrudníku; paty na zemi; kolena sledují špičky; trup stabilní; hloubka bez ztráty kontroly.", "chyby": "Činka se vzdaluje od těla — přitáhni ji k hrudníku. Paty se zvedají — zkrať hloubku nebo uprav postoj. Kolena padají dovnitř — kontroluj směr kolen. Záda se hroutí — sniž zátěž.", "dychani": "Nádech při sestupu, výdech při vstávání; trup zpevni před pohybem.", "varianty": "Regrese: dřep na lavičku bez zátěže. Progrese: těžší kettlebell, pauza dole nebo pomalejší sestup.", "davkovani": "3 série × 8–12 opakování; pauza 60–120 s.", "poporodni_poznamka": "Vhodná varianta pro návrat k dřepům díky snadno škálovatelné zátěži. Sleduj případné příznaky pánevního dna a břišní stěny.", "category": "Nohy a hýždě"}, {"id": 4, "number": "004", "title": "Leg Press", "english": "Leg Press", "typ": "Vícekloubový tlak; posilovací stroj", "anatomie": "Kvadricepsy; významně také hýžďové svaly podle hloubky a polohy chodidel; pomocně adduktory a hamstringy.", "biomechanika": "Kyčle a kolena se ohýbají při spouštění plošiny a natahují při tlaku. Kotníky se přizpůsobují pohybu.", "vychozi_pozice": "Opři záda a pánev o opěrku. Chodidla polož na plošinu přibližně na šířku ramen. Kolena směřují ve směru špiček. Uvolni bezpečnostní pojistky podle návodu stroje.", "provedeni": "Kontrolovaně spouštěj plošinu, dokud udržíš pánev a bedra opřená. Zatlač plošinu vzhůru přes celé chodidlo; kolena nahoře nezamykej prudce.", "spravna_technika": "Pánev zůstává na opěrce; kolena sledují špičky; pohyb je plynulý; rozsah končí před podsazením pánve nebo bolestí.", "chyby": "Pánev se odlepuje — zkrať hloubku. Kolena padají dovnitř — uprav zátěž a kontrolu. Propínání kolen do zámku — zastav těsně před ním. Odraz od spodní pozice — zpomal.", "dychani": "Nádech při spouštění, výdech při tlaku; trup drž stabilní a neprohýbej bedra.", "varianty": "Regrese: lehčí zátěž a menší rozsah. Progrese: postupné přidání zátěže nebo kontrolovanější tempo.", "davkovani": "3 série × 8–12 opakování; pauza 90–120 s.", "poporodni_poznamka": "Zvol rozsah, při kterém se pánev neodlepuje a necítíš tlak v pánevním dnu. Nezvyšuj zátěž na úkor kontroly.", "category": "Nohy a hýždě"}, {"id": 5, "number": "005", "title": "Rumunský Mrtvý Tah", "english": "Romanian Deadlift (RDL)", "typ": "Vícekloubový kyčelní tah; osa nebo jednoručky", "anatomie": "Hamstringy a velký hýžďový sval; pomocně adduktor magnus; stabilizují vzpřimovače páteře, široký sval zádový a břišní svaly.", "biomechanika": "Dominantní extenze kyčle. Kolena zůstávají mírně pokrčená a jejich úhel se mění jen málo. Hamstringy se prodlužují při posunu kyčlí dozadu.", "vychozi_pozice": "Stůj na šířku boků, zátěž před stehny. Kolena mírně povol, žebra drž nad pánví a nastav neutrální stabilní páteř.", "provedeni": "Pošli kyčle dozadu, zátěž veď těsně podél stehen a holení. Klesej jen do rozsahu, v němž udržíš páteř a napětí hamstringů. Zatlač chodidly do země a vrať kyčle vpřed.", "spravna_technika": "Pohyb vychází z kyčlí; kolena zůstávají lehce pokrčená; zátěž blízko těla; páteř stabilní; nahoře bez záklonu.", "chyby": "Mění se cvik na dřep — méně pokrč kolena. Zátěž se vzdaluje — drž ji u nohou. Kulacení zad — zkrať rozsah. Záklon nahoře — skonči ve vzpřímení.", "dychani": "Nádech před pohybem a při cestě dolů; vydechuj při návratu. Udržuj pevný, ale ne křečovitý trup.", "varianty": "Regrese: nácvik hip hinge s tyčí nebo RDL s lehkými jednoručkami. Progrese: vyšší zátěž, jednonožní RDL nebo pomalý sestup.", "davkovani": "3 série × 8–10 opakování; pauza 90–150 s.", "poporodni_poznamka": "Začni lehkou zátěží a kratším rozsahem. Při vyklenování břišní stěny, tlaku v pánvi, úniku moči či bolesti zátěž uprav a konzultuj fyzioterapeutku.", "category": "Nohy a hýždě"}, {"id": 6, "number": "006", "title": "Hip Thrust", "english": "Barbell Hip Thrust", "typ": "Vícekloubová extenze kyčle; lavička a osa", "anatomie": "Hlavní: velký hýžďový sval. Pomocně hamstringy a adduktor magnus; stabilizují břišní svaly a svaly kolem kyčlí.", "biomechanika": "Extenze kyčle proti odporu. Zatížení hýžďových svalů se mění v průběhu dráhy podle nastavení těla a odporu; kolena zůstávají pokrčená.", "vychozi_pozice": "Horní část zad opři o lavičku, chodidla na šířku boků a osa přes kyčelní ohyb s vhodnou podložkou. V horní pozici mají holeně přibližně svislou polohu; uprav podle proporcí.", "provedeni": "Spusť pánev kontrolovaně. Zatlač chodidly do země a zvedej pánev extenzí kyčlí. Nahoře skonči, když je trup a stehna přibližně v jedné linii; nepřehýbej bedra.", "spravna_technika": "Brada lehce přitažená; žebra nad pánví; tlak přes celé chodidlo; pohyb v kyčlích; nahoře bez bederního záklonu.", "chyby": "Přehýbání v bedrech — ukonči pohyb dřív. Chodidla příliš daleko — uprav jejich polohu. Tlak jen do špiček — rozlož oporu. Nekontrolovaný sestup — zpomal.", "dychani": "Nádech při spouštění, výdech při zvedání. V horní pozici vydechni bez násilného zatínání břicha.", "varianty": "Regrese: glute bridge na zemi. Progrese: přidání zátěže, pauza nahoře nebo jednonožní varianta až při dobré kontrole.", "davkovani": "3 série × 8–12 opakování; pauza 90–120 s.", "poporodni_poznamka": "Začni glute bridge nebo lehkým hip thrustem. Sleduj tlak v pánvi a schopnost dýchat bez vyklenování břišní stěny.", "category": "Nohy a hýždě"}, {"id": 7, "number": "007", "title": "Most Na Zemi", "english": "Glute Bridge", "typ": "Vícekloubová extenze kyčle; podložka, volitelně zátěž", "anatomie": "Hlavní: velký hýžďový sval. Pomocně hamstringy; stabilizují břišní svaly a svaly kolem pánve.", "biomechanika": "Extenze kyčle při zvednutí pánve. Pokrčení kolen zůstává přibližně stejné. Vzdálenost chodidel mění relativní nároky na hamstringy.", "vychozi_pozice": "Lehni na záda, pokrč kolena, chodidla polož na šířku boků. Ruce podél těla, žebra uvolněná, pánev v pohodlné neutrální pozici.", "provedeni": "Zpevni trup, zatlač chodidly do podlahy a zvedni pánev. Nahoře aktivuj hýždě bez přehnutí beder. Pomalu spusť pánev dolů.", "spravna_technika": "Chodidla stabilní; kolena se nerozjíždějí; pohyb vychází z kyčlí; žebra zůstávají klidná; nevyháněj pánev výš za cenu prohnutí.", "chyby": "Tlačení do beder — sniž výšku. Kolena padají dovnitř — kontroluj osu. Křeče hamstringů — uprav vzdálenost chodidel. Odraz a rychlý sestup — zpomal.", "dychani": "Vydechni při zvednutí, nadechni se při spouštění. Dýchej plynule.", "varianty": "Regrese: menší rozsah nebo izometrické držení. Progrese: miniband nad koleny, zátěž na pánvi, march nebo jednonožní varianta.", "davkovani": "2–3 série × 10–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Často vhodný začátek posilování hýždí po porodu, pokud je bez příznaků. Nepřidávej obtížnost při tlaku, bolesti nebo zhoršení kontroly břišní stěny.", "category": "Nohy a hýždě"}, {"id": 8, "number": "008", "title": "Bulharský Dřep", "english": "Bulgarian Split Squat", "typ": "Vícekloubový jednostranný dřep; lavička, volitelně jednoručky", "anatomie": "Kvadricepsy a velký hýžďový sval; pomocně adduktory a hamstringy; stabilizují střední hýžďový sval, břišní svaly a svaly kotníku.", "biomechanika": "Přední kyčel a koleno se ohýbají při sestupu a natahují při výstupu. Zadní noha slouží hlavně jako opora.", "vychozi_pozice": "Postav se zády k lavičce a polož nárt zadní nohy na oporu. Přední chodidlo nastav tak, abys měla stabilní rovnováhu. Pánev směřuje vpřed, trup může být mírně nakloněný.", "provedeni": "Klesej dolů pokrčením předního kolena a kyčle. Přední chodidlo zůstává celé na zemi. Zatlač přes přední nohu a vrať se vzhůru; zadní noha pomáhá jen podle potřeby.", "spravna_technika": "Stabilní přední chodidlo; koleno sleduje směr špičky; pánev kontrolovaná; hloubka odpovídá mobilitě a rovnováze; tlak převážně přes přední nohu.", "chyby": "Příliš krátký postoj — uprav vzdálenost. Koleno padá dovnitř — sniž zátěž. Odraz zadní nohou — přenes práci dopředu. Příliš hluboký sestup — zkrať rozsah.", "dychani": "Nádech při sestupu, výdech při výstupu. Zpevni trup a udrž rovnováhu.", "varianty": "Regrese: split squat s oběma nohama na zemi a oporou ruky. Progrese: jednoručky, větší rozsah nebo pomalý sestup.", "davkovani": "2–3 série × 8–10 opakování na nohu; pauza 90–120 s.", "poporodni_poznamka": "Vyžaduje rovnováhu a dobrou kontrolu pánve. Začni bez zátěže a s oporou; při příznacích pánevního dna zvol jednodušší variantu.", "category": "Nohy a hýždě"}, {"id": 9, "number": "009", "title": "Výpady Vzad", "english": "Reverse Lunge", "typ": "Vícekloubový jednostranný cvik; vlastní váha nebo jednoručky", "anatomie": "Kvadricepsy a hýžďové svaly; pomocně adduktory a hamstringy; stabilizují střední hýžďové svaly, lýtka a trup.", "biomechanika": "Přední kyčel a koleno se ohýbají při kroku vzad a natahují při návratu. Zadní noha pomáhá s rovnováhou a může se podílet na odrazu; míra zatížení přední nohy závisí na délce kroku a sklonu trupu.", "vychozi_pozice": "Stůj vzpřímeně, chodidla pod kyčlemi. Zpevni trup, pánev drž rovně. Zátěž může být podél těla.", "provedeni": "Ustup jednou nohou dozadu a klesej kontrolovaně dolů. Přední koleno se může přirozeně posunout před špičku, pokud pata zůstává opřená a pohyb je bez bolesti. Zatlač přední nohou a vrať se do stoje.", "spravna_technika": "Přední chodidlo stabilní; koleno sleduje směr špičky; pánev se neotáčí; krok je dostatečně dlouhý pro rovnováhu; návrat bez odrazu.", "chyby": "Úzká „kolej“ — rozšiř postoj do dvou stop. Přední pata se zvedá — uprav délku kroku. Nekontrolovaný dopad — zpomal. Trup se hroutí — zvol menší rozsah.", "dychani": "Nádech při kroku a sestupu, výdech při návratu. Udržuj plynulé dýchání.", "varianty": "Regrese: krátký krok s oporou nebo split squat. Progrese: jednoručky, deficitní výpad jen při dobré kontrole.", "davkovani": "2–3 série × 8–12 opakování na nohu; pauza 60–90 s.", "poporodni_poznamka": "Začni s vlastní vahou a menším rozsahem. Sleduj rovnováhu a případný tlak či tíhu v pánevním dnu.", "category": "Nohy a hýždě"}, {"id": 10, "number": "010", "title": "Výstupy Na Lavičku", "english": "Step-up", "typ": "Vícekloubový jednostranný cvik; step/lavička, volitelně jednoručky", "anatomie": "Kvadricepsy a velký hýžďový sval; pomocně hamstringy a lýtka; stabilizují střední a malý hýžďový sval, svaly trupu a kotníku.", "biomechanika": "Extenze kyčle a kolena při výstupu; kontrolovaná flexe při sestupu. Kotník se přizpůsobuje výšce stepu.", "vychozi_pozice": "Postav se před stabilní nízký step. Polož celé pracovní chodidlo na plošinu. Pánev rovně, trup stabilní, koleno ve směru chodidla.", "provedeni": "Zatlač pracovní nohou do stepu a vystoupej do stoje. Zadní nohou se odrážej co nejméně. Sestupuj pomalu a kontrolovaně.", "spravna_technika": "Celé chodidlo na stepu; koleno sleduje chodidlo; pánev neklesá do strany; bez odrazu zadní nohou; kontrolovaný sestup.", "chyby": "Odraz zadní nohou — sniž výšku a soustřeď se na pracovní nohu. Koleno dovnitř — sniž zátěž. Příliš vysoký step — zvol nižší. Dopad dolů — zpomal sestup.", "dychani": "Nádech při přípravě a sestupu, výdech při výstupu. Trup stabilní, dech plynulý.", "varianty": "Regrese: nižší step a opora ruky. Progrese: jednoručky, vyšší step pouze při čisté technice, pomalý sestup.", "davkovani": "2–3 série × 8–12 opakování na nohu; pauza 60–90 s.", "poporodni_poznamka": "Začni nízkým stepem a vlastní vahou. Při tlaku v pánvi, úniku moči, bolesti nebo vyklenování břišní stěny sniž náročnost.", "category": "Nohy a hýždě"}, {"id": 11, "number": "011", "title": "Zakopávání", "english": "Leg Curl", "typ": "Jednokloubová izolace; stroj vsedě nebo vleže", "anatomie": "Hlavní: hamstringy – biceps femoris, semitendinosus, semimembranosus. Pomocně gastrocnemius.", "biomechanika": "Flexe kolena proti odporu; kyčel zůstává podle konstrukce stroje stabilní. Hamstringy jsou také extenzory kyčle, ale zde pracují hlavně jako flexory kolena.", "vychozi_pozice": "Nastav osu otáčení stroje přibližně do úrovně kolenního kloubu. Opěrný válec umísti nad paty či dolní část lýtek dle stroje. Pánev a trup opři podle varianty.", "provedeni": "Pokrč kolena a přitáhni paty směrem k hýždím bez švihu. V krajní pozici krátce kontroluj kontrakci a pomalu vrať nohy do výchozí polohy; nepropínej kolena násilně.", "spravna_technika": "Pánev zůstává opřená; pohyb probíhá v kolenou; návrat pomalý; rozsah bez bolesti.", "chyby": "Zvedání pánve — sniž zátěž. Švih — zpomal. Příliš krátký rozsah — uprav nastavení. Bolest za kolenem — přeruš a zkontroluj polohu.", "dychani": "Vydechuj při zakopnutí, nadechuj při návratu.", "varianty": "Regrese: menší zátěž nebo kratší rozsah. Progrese: vyšší zátěž, pauza v kontrakci nebo jednonožní varianta.", "davkovani": "2–3 série × 10–15 opakování; pauza 60–90 s.", "poporodni_poznamka": "Obvykle lze dobře škálovat. Zvol zátěž bez zadržování dechu a bez tlaku v pánvi.", "category": "Nohy a hýždě"}, {"id": 12, "number": "012", "title": "Předkopávání", "english": "Leg Extension", "typ": "Jednokloubová izolace; stroj", "anatomie": "Hlavní: kvadriceps – rectus femoris, vastus lateralis, medialis a intermedius.", "biomechanika": "Extenze kolena proti odporu. Kyčel zůstává stabilní; přímý sval stehenní překračuje kyčel i koleno.", "vychozi_pozice": "Nastav osu stroje do úrovně kolenního kloubu. Opěrný válec umísti na dolní část holeně nad kotníky. Záda a pánev opři o sedadlo.", "provedeni": "Natahuj kolena plynule bez kopnutí. V horní pozici krátce kontroluj pohyb, poté pomalu spouštěj zpět.", "spravna_technika": "Pánev zůstává opřená; kolena se pohybují v ose stroje; bez švihu; rozsah bez bolesti.", "chyby": "Zvedání pánve — sniž zátěž. Kopání švihem — zpomal. Nesprávné nastavení osy — uprav stroj. Bolest kolene — zmenši rozsah nebo cvik vynech.", "dychani": "Výdech při natažení, nádech při návratu.", "varianty": "Regrese: menší zátěž a rozsah. Progrese: postupné zvýšení zátěže, pauza nahoře nebo jednostranné provedení.", "davkovani": "2–3 série × 10–15 opakování; pauza 60–90 s.", "poporodni_poznamka": "Při citlivosti kolen začni lehce a sleduj reakci během i po tréninku. Nepřekonávej bolest.", "category": "Nohy a hýždě"}, {"id": 13, "number": "013", "title": "Unožování Na Stroji", "english": "Hip Abduction Machine", "typ": "Izolovaný cvik; stroj", "anatomie": "Hlavní: střední a malý hýžďový sval. Pomocně horní vlákna velkého hýžďového svalu a tensor fasciae latae.", "biomechanika": "Abdukce kyčle – stehna se vzdalují od střední osy těla. Pánev a trup stabilizují polohu.", "vychozi_pozice": "Sedni si, opři záda a nastav kolenní opěrky na vnější stranu stehen. Pánev v neutrální pozici, chodidla uvolněná.", "provedeni": "Tlač kolena od sebe plynule proti odporu. Zastav před tím, než se začne pohybovat pánev. Vrať kolena pomalu k sobě.", "spravna_technika": "Pánev stabilní; pohyb vychází z kyčlí; bez švihu; kontrolovaný návrat.", "chyby": "Naklánění trupu — sniž zátěž. Krátký švih — zpomal. Příliš velký rozsah s rotací pánve — zkrať rozsah.", "dychani": "Výdech při unožení, nádech při návratu.", "varianty": "Regrese: miniband vestoje nebo vleže na boku bez zátěže. Progrese: vyšší odpor, pomalý návrat.", "davkovani": "2–3 série × 12–20 opakování; pauza 45–75 s.", "poporodni_poznamka": "Vnímej práci boční části hýždí, ne bolest kyčle. Zátěž má umožnit stabilní pánev.", "category": "Nohy a hýždě"}, {"id": 14, "number": "014", "title": "Přinožování Na Stroji", "english": "Hip Adduction Machine", "typ": "Izolovaný cvik; stroj", "anatomie": "Hlavní: adduktory stehna – adductor magnus, longus, brevis, gracilis a pectineus.", "biomechanika": "Addukce kyčle – stehna se přibližují ke střední ose těla. Pánev stabilizuje sed.", "vychozi_pozice": "Nastav opěrky na vnitřní stranu stehen a zvol pohodlný rozsah roztažení. Záda a pánev opři o sedadlo.", "provedeni": "Přitahuj stehna k sobě plynule. Krátce zastav bez prudkého stlačení a kontrolovaně vrať do výchozí polohy.", "spravna_technika": "Pánev zůstává opřená; pohyb vychází z kyčlí; bez švihu; rozsah bez nepříjemného tahu.", "chyby": "Příliš velké roztažení — zmenši startovní rozsah. Švih — sniž zátěž. Zvedání pánve — opři trup a uprav nastavení.", "dychani": "Výdech při přinožení, nádech při návratu.", "varianty": "Regrese: lehký odpor nebo izometrické stlačení míče mezi koleny. Progrese: postupné zvýšení zátěže.", "davkovani": "2–3 série × 10–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Začni lehce; při nepříjemném tahu v tříslech nebo pánvi rozsah zmenši či cvik vynech.", "category": "Nohy a hýždě"}, {"id": 15, "number": "015", "title": "Výpony Na Lýtka", "english": "Calf Raise", "typ": "Izolovaný cvik; stroj, schod nebo jednoručky", "anatomie": "Hlavní: gastrocnemius a soleus. Pomocně svaly chodidla a peroneální svaly.", "biomechanika": "Plantární flexe kotníku – zvednutí paty. S nataženým kolenem je relativně více zatížen gastrocnemius; s pokrčeným soleus.", "vychozi_pozice": "Stůj s přední částí chodidel na podložce nebo plošině, paty volně. Přidrž se opory a nastav kolena podle varianty.", "provedeni": "Zvedni paty co nejvýše v pohodlném rozsahu. Krátce zastav a pomalu spusť paty dolů bez odrazu.", "spravna_technika": "Tlak přes palcovou a malíkovou hranu přednoží; kotníky se nevyklánějí; plný kontrolovaný rozsah.", "chyby": "Odraz — zpomal. Kotníky padají ven či dovnitř — sniž zátěž. Příliš rychlé spouštění — kontroluj excentrickou fázi.", "dychani": "Vydechuj při zvednutí, nadechuj při spouštění.", "varianty": "Regrese: výpony vsedě bez zátěže. Progrese: jednonožní výpony nebo přidaná zátěž.", "davkovani": "2–3 série × 10–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Začni oběma nohama a přidržuj se. Sleduj rovnováhu a případné potíže v oblasti pánevního dna.", "category": "Nohy a hýždě"}, {"id": 16, "number": "016", "title": "Stahování Horní Kladky", "english": "Lat Pulldown", "typ": "Vícekloubový vertikální tah; horní kladka", "anatomie": "Hlavní: široký sval zádový a velký oblý sval. Pomocně biceps, brachialis, brachioradialis; svaly střední a dolní části trapézu a rombické svaly se podílejí na řízení lopatek.", "biomechanika": "Addukce a extenze ramene, flexe lokte; lopatky se pohybují kontrolovaně dolů a podle úchopu rotují.", "vychozi_pozice": "Sedni si, zajisti stehna pod opěrkou. Uchop tyč o něco širším než ramenním úchopem podle pohodlí. Trup vzpřímený s mírným náklonem, žebra nad pánví.", "provedeni": "Začni kontrolovaným pohybem lopatek a táhni lokty dolů k bokům. Tyč přibliž k horní části hrudníku bez zaklánění. Pomalu vrať paže vzhůru.", "spravna_technika": "Ramena nevyjíždějí k uším; trup stabilní; lokty táhnou dolů; návrat kontrolovaný; bez bolesti ramene.", "chyby": "Tah za hlavu — táhni před tělo. Zaklánění — sniž zátěž. Tah pouze rukama — soustřeď se na lokty. Nekontrolované vytažení nahoru — zpomal.", "dychani": "Výdech při tahu dolů, nádech při návratu vzhůru.", "varianty": "Regrese: lehčí zátěž nebo asistovaný stah. Progrese: těžší zátěž, pauza dole nebo jednoruční stah.", "davkovani": "3 série × 8–12 opakování; pauza 60–90 s.", "poporodni_poznamka": "Dobře škálovatelný cvik pro posílení zad. Udržuj dech a nekompenzuj pohyb záklonem.", "category": "Záda a ramena"}, {"id": 17, "number": "017", "title": "Přítahy Vsedě", "english": "Seated Cable Row", "typ": "Vícekloubový horizontální tah; kladka", "anatomie": "Hlavní: střední část zad – rombické svaly a střední trapéz, široký sval zádový. Pomocně zadní delty a flexory lokte.", "biomechanika": "Extenze ramene a retrakce lopatek, flexe loktů. Trup zůstává stabilní.", "vychozi_pozice": "Sedni si s chodidly na opěrkách, kolena lehce pokrčená. Uchop madlo, narovnej páteř a nastav ramena volně dolů.", "provedeni": "Táhni madlo k oblasti břicha, lokty vedou pohyb dozadu. Lopatky se přirozeně přiblíží. Vrať ruce dopředu bez zhroucení trupu.", "spravna_technika": "Trup se nehoupá; ramena zůstávají mimo uši; lokty míří dozadu; návrat kontrolovaný.", "chyby": "Houpání trupem — sniž zátěž. Zvedání ramen — uvolni trapézy. Přehnané zaklánění — drž stabilní trup. Zkrácený návrat — dovol lopatkám kontrolovaný pohyb vpřed.", "dychani": "Výdech při přítahu, nádech při návratu.", "varianty": "Regrese: lehčí odpor a kratší rozsah. Progrese: pauza v přitažení, jednoruční varianta.", "davkovani": "3 série × 8–12 opakování; pauza 60–90 s.", "poporodni_poznamka": "Užitečný cvik pro sílu zad při každodenním nošení. Nezaměňuj práci lopatek za prohýbání beder.", "category": "Záda a ramena"}, {"id": 18, "number": "018", "title": "Přítah Jednoručky V Předklonu", "english": "Single-arm Dumbbell Row", "typ": "Vícekloubový jednostranný tah; jednoručka a opora", "anatomie": "Hlavní: široký sval zádový a svaly střední části zad. Pomocně zadní delty, biceps; stabilizují šikmé břišní svaly a vzpřimovače.", "biomechanika": "Extenze ramene a flexe lokte; lopatka se kontrolovaně pohybuje. Trup odolává rotaci.", "vychozi_pozice": "Jednou rukou a případně kolenem se opři o lavičku. Druhé chodidlo pevně na zemi. Páteř stabilní, rameno pracovní paže volně dolů.", "provedeni": "Táhni loket směrem k boku nebo kyčli, aniž bys otáčela trupem. Pomalu spouštěj jednoručku do protažení pod kontrolou.", "spravna_technika": "Trup stabilní; rameno se nevytahuje k uchu; loket vede pohyb; bez rotace trupu; kontrolovaný rozsah.", "chyby": "Rotace trupu — sniž zátěž. Tah k rameni místo k boku — uprav dráhu podle cíle. Švih — zpomal. Kulacení zad — nastav oporu a páteř.", "dychani": "Výdech při přítahu, nádech při spouštění.", "varianty": "Regrese: přítah s lehkou gumou. Progrese: vyšší zátěž, pauza nahoře nebo přítah bez opory při stabilním trupu.", "davkovani": "3 série × 8–12 opakování na stranu; pauza 60–90 s.", "poporodni_poznamka": "Jednostranná práce rozvíjí i odolnost trupu proti rotaci. Začni s oporou a lehkou zátěží.", "category": "Záda a ramena"}, {"id": 19, "number": "019", "title": "Přítahy Osy V Předklonu", "english": "Barbell Bent-over Row", "typ": "Vícekloubový horizontální tah; osa", "anatomie": "Hlavní: široký sval zádový a střední část zad. Pomocně zadní delty, biceps; stabilizují vzpřimovače páteře, hamstringy a břišní svaly.", "biomechanika": "Extenze ramene a flexe lokte; trup drží izometrickou kyčelní pozici.", "vychozi_pozice": "Postav se na šířku boků, proveď hip hinge a uchop osu. Kolena mírně pokrčená, páteř stabilní, osa pod rameny.", "provedeni": "Táhni osu k dolní části žeber nebo břichu podle úchopu. Lokty vedou dozadu. Spouštěj osu kontrolovaně bez změny polohy trupu.", "spravna_technika": "Stabilní předklon; osa blízko těla; ramena mimo uši; bez houpání; krk v prodloužení páteře.", "chyby": "Trup se zvedá při každém tahu — sniž zátěž. Kulacení zad — zkrať sérii či uprav předklon. Švih — zpomal. Ramena k uším — uvolni je.", "dychani": "Nadechni se a zpevni před sérií; vydechuj při přítahu, nadechuj při spouštění.", "varianty": "Regrese: přítahy s oporou hrudníku nebo jednoručky. Progrese: vyšší zátěž či pauza u trupu.", "davkovani": "3 série × 6–10 opakování; pauza 90–150 s.", "poporodni_poznamka": "Kvůli nárokům na stabilizaci trupu začni lehce. Pokud nedokážeš udržet polohu bez zadržování dechu, zvol variantu s oporou.", "category": "Záda a ramena"}, {"id": 20, "number": "020", "title": "Přítahy S Oporou Hrudníku", "english": "Chest-supported Row", "typ": "Vícekloubový horizontální tah; šikmá lavička a jednoručky/stroj", "anatomie": "Hlavní: široký sval zádový, rombické svaly a trapézy. Pomocně zadní delty a biceps.", "biomechanika": "Extenze ramene, retrakce lopatek a flexe loktů; opora hrudníku omezuje nároky na stabilizaci trupu.", "vychozi_pozice": "Nastav lavičku šikmo, opři hrudník a chodidla stabilně o zem. Paže volně visí, krk v prodloužení páteře.", "provedeni": "Táhni lokty dozadu a přibliž lopatky bez zvedání ramen. Pomalu spouštěj činky do kontrolovaného protažení.", "spravna_technika": "Hrudník zůstává na opěrce; ramena mimo uši; zápěstí neutrální; pohyb bez švihu.", "chyby": "Odlepování hrudníku — sniž zátěž. Zvedání ramen — uprav dráhu loktů. Zkrácený rozsah — zvol lehčí váhu.", "dychani": "Výdech při přítahu, nádech při návratu.", "varianty": "Regrese: lehčí jednoručky nebo stroj. Progrese: vyšší zátěž, pauza nahoře.", "davkovani": "3 série × 8–12 opakování; pauza 60–90 s.", "poporodni_poznamka": "Varianta s oporou může být vhodná, když chceš posílit záda bez velkých nároků na bedra.", "category": "Záda a ramena"}, {"id": 21, "number": "021", "title": "Face Pull", "english": "Face Pull", "typ": "Tahový cvik na horní část zad a ramena; kladka s lanem", "anatomie": "Hlavní: zadní delty, střední a dolní trapéz, rombické svaly. Pomocně zevní rotátory ramene.", "biomechanika": "Horizontální abdukce a zevní rotace ramene, retrakce lopatek; lokty se ohýbají.", "vychozi_pozice": "Nastav kladku přibližně do výšky obličeje. Uchop lano neutrálně, ustup do stabilního postoje, trup vzpřímený.", "provedeni": "Táhni lano směrem k obličeji a odděluj konce lana. Lokty míří do stran, předloktí se otáčejí podle možností ramene. Vrať pomalu.", "spravna_technika": "Ramena dole; žebra nad pánví; lokty přiměřeně vysoko; bez bolesti a bez záklonu.", "chyby": "Tah k hrudníku místo obličeje — uprav výšku kladky. Záklon — sniž zátěž. Zvedání ramen — uvolni je. Přehnaná zevní rotace — zkrať rozsah.", "dychani": "Výdech při tahu, nádech při návratu.", "varianty": "Regrese: lehčí guma nebo kladka. Progrese: pauza v konci tahu, pomalejší návrat.", "davkovani": "2–3 série × 12–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Pracuj s lehkou až střední zátěží; cílem je kontrola lopatek a ramen, ne maximální váha.", "category": "Záda a ramena"}, {"id": 22, "number": "022", "title": "Upažování S Jednoručkami", "english": "Dumbbell Lateral Raise", "typ": "Izolovaný cvik; jednoručky", "anatomie": "Hlavní: střední část deltového svalu. Pomocně supraspinatus a horní trapéz.", "biomechanika": "Abdukce ramene v rovině lopatky; lopatka se přirozeně otáčí vzhůru.", "vychozi_pozice": "Stůj vzpřímeně, jednoručky podél těla, lokty lehce pokrčené. Ramena volně dolů, trup stabilní.", "provedeni": "Zvedej paže do stran přibližně do výšky ramen nebo do pohodlného rozsahu. Lokty vedou pohyb. Pomalu spouštěj.", "spravna_technika": "Lehký ohyb loktů; zápěstí neutrální; bez švihu; ramena nevytahuj k uším; rozsah bez bolesti.", "chyby": "Houpání trupem — sniž váhu. Zvedání ramen — zmenši zátěž. Činky příliš vpředu — drž pohyb v rovině lopatek. Příliš vysoko — zkrať rozsah.", "dychani": "Výdech při zvedání, nádech při spouštění.", "varianty": "Regrese: lehčí činky nebo kladka/guma. Progrese: pomalejší excentrická fáze, pauza v horní pozici.", "davkovani": "2–3 série × 10–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Zvol váhu, se kterou zvládneš pohyb bez švihu. Při bolesti ramene uprav rozsah nebo cvik nahraď.", "category": "Záda a ramena"}, {"id": 23, "number": "023", "title": "Předpažování", "english": "Front Raise", "typ": "Izolovaný cvik; jednoručky, kotouč nebo kladka", "anatomie": "Hlavní: přední část deltového svalu. Pomocně horní část prsního svalu a biceps.", "biomechanika": "Flexe ramene; lopatka se přirozeně otáčí vzhůru.", "vychozi_pozice": "Stůj stabilně, zátěž před stehny, lokty lehce pokrčené. Žebra nad pánví, ramena uvolněná.", "provedeni": "Zvedej paže před tělo do výšky ramen nebo pohodlného rozsahu. Pomalu spouštěj bez švihu.", "spravna_technika": "Trup neuhýbá; lokty lehce pokrčené; ramena nevytahuj k uším; kontrolovaný rozsah.", "chyby": "Záklon — sniž zátěž. Švih — zpomal. Zvedání nad bolestivý rozsah — zkrať pohyb. Zápěstí se láme — drž neutrální pozici.", "dychani": "Výdech při zvedání, nádech při spouštění.", "varianty": "Regrese: lehká zátěž nebo střídavé předpažování. Progrese: kladka, pauza nebo pomalý sestup.", "davkovani": "2–3 série × 10–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Přední delty pracují i při tlacích na hrudník a ramena. Přidávej izolaci podle celkového objemu tréninku.", "category": "Záda a ramena"}, {"id": 24, "number": "024", "title": "Tlaky Nad Hlavu", "english": "Shoulder Press", "typ": "Vícekloubový vertikální tlak; jednoručky nebo stroj", "anatomie": "Hlavní: přední a střední delty. Pomocně triceps a horní část prsního svalu; stabilizují rotátorová manžeta, trapézy a svaly trupu.", "biomechanika": "Flexe/abdukce ramene a extenze lokte; lopatky rotují vzhůru. Trup odolává nadměrnému prohnutí.", "vychozi_pozice": "Sedni nebo stůj stabilně. Jednoručky u ramen, předloktí přibližně pod činkami. Žebra nad pánví, chodidla pevně.", "provedeni": "Tlač činky vzhůru v dráze, která je pohodlná pro ramena. Nahoře paže téměř propnuté bez násilného zamčení. Spouštěj kontrolovaně.", "spravna_technika": "Trup stabilní; bez záklonu; zápěstí nad lokty; ramena se pohybují přirozeně; bez bolesti.", "chyby": "Prohýbání beder — sniž zátěž nebo cvič vsedě s oporou. Činky se srážejí — kontroluj dráhu. Lokty příliš dozadu — uprav startovní polohu.", "dychani": "Nádech při spouštění, výdech při tlaku vzhůru.", "varianty": "Regrese: stroj nebo lehké jednoručky vsedě. Progrese: stojná varianta, vyšší zátěž nebo jednostranný tlak.", "davkovani": "3 série × 8–10 opakování; pauza 90 s.", "poporodni_poznamka": "Začni lehkou variantou a sleduj, zda tlak nevyvolává vyklenování břišní stěny nebo tlak v pánevním dnu.", "category": "Záda a ramena"}, {"id": 25, "number": "025", "title": "Obrácené Rozpažování", "english": "Reverse Fly", "typ": "Izolovaný cvik; jednoručky, stroj nebo kladka", "anatomie": "Hlavní: zadní delty. Pomocně rombické svaly a střední trapéz; stabilizují svaly rotátorové manžety.", "biomechanika": "Horizontální abdukce ramene a kontrolovaný pohyb lopatek.", "vychozi_pozice": "Předkloň se z kyčlí nebo použij stroj s oporou hrudníku. Paže visí pod rameny, lokty lehce pokrčené, krk uvolněný.", "provedeni": "Rozpaž paže do stran, dokud jsou v linii trupu nebo v pohodlném rozsahu. Pomalu vrať dolů.", "spravna_technika": "Pohyb v ramenou; trup stabilní; lokty lehce pokrčené; bez švihu a bez zvedání ramen.", "chyby": "Houpání trupem — sniž zátěž. Přehnané stahování lopatek — zmenši rozsah. Zvedání ramen — uvolni krk. Příliš propnuté lokty — lehce je pokrč.", "dychani": "Výdech při rozpažení, nádech při návratu.", "varianty": "Regrese: stroj s oporou hrudníku nebo lehká guma. Progrese: kladka, pauza v konci rozsahu.", "davkovani": "2–3 série × 12–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Lehká zátěž obvykle stačí. Prioritou je přesnost pohybu, nikoli velká váha.", "category": "Záda a ramena"}, {"id": 26, "number": "026", "title": "Krčení Ramen", "english": "Dumbbell Shrug", "typ": "Izolovaný cvik; jednoručky nebo osa", "anatomie": "Hlavní: horní trapéz. Pomocně zdvihač lopatky a svaly předloktí při úchopu.", "biomechanika": "Elevace lopatek – ramena se zvedají směrem k uším; krční páteř zůstává neutrální.", "vychozi_pozice": "Stůj vzpřímeně s činkami podél těla. Paže natažené, ramena uvolněná, hlava v neutrální poloze.", "provedeni": "Zvedni ramena vzhůru bez kroužení. Krátce podrž a kontrolovaně spusť dolů.", "spravna_technika": "Pohyb přímo vzhůru; hlava se neposouvá; lokty zůstávají natažené; bez kroužení ramen.", "chyby": "Kroužení ramen — zvedej přímo vzhůru. Krčení loktů — nech paže dlouhé. Předsunutá hlava — drž krk neutrálně. Švih — sniž zátěž.", "dychani": "Vydechuj při zvednutí, nadechuj při spouštění.", "varianty": "Regrese: lehčí činky. Progrese: těžší zátěž nebo pauza nahoře.", "davkovani": "2–3 série × 10–15 opakování; pauza 60–90 s.", "poporodni_poznamka": "Není nutné zařazovat automaticky; trapézy pracují i při nošení a přenášení zátěže.", "category": "Záda a ramena"}, {"id": 27, "number": "027", "title": "Hyperextenze", "english": "Back Extension", "typ": "Vícekloubová extenze trupu/kyčle; lavice na hyperextenze", "anatomie": "Podle provedení: vzpřimovače páteře, velký hýžďový sval a hamstringy. Stabilizují břišní svaly.", "biomechanika": "Při kyčelní variantě se trup pohybuje v kyčlích; při páteřní variantě probíhá extenze páteře. Je důležité vědět, kterou variantu provádíš.", "vychozi_pozice": "Nastav opěrku pod kyčelní ohyb tak, aby se pánev mohla volně pohybovat. Chodidla zajisti, trup v prodloužení nohou.", "provedeni": "Pro variantu na hýždě a hamstringy sklop trup z kyčlí a vrať se do přímé linie tlakem přes kyčle. Nepokračuj do záklonu.", "spravna_technika": "Pohyb kontrolovaný; krk v prodloužení páteře; konec v přímé linii; bez švihu.", "chyby": "Přehnaný záklon — skonči v rovině těla. Houpání — sniž rozsah. Pohyb pouze v bedrech, když chceš kyčelní variantu — uč se hinge.", "dychani": "Nádech při spouštění, výdech při návratu do roviny.", "varianty": "Regrese: kratší rozsah nebo lehčí varianty hip hinge. Progrese: ruce na hrudníku, následně lehká zátěž.", "davkovani": "2–3 série × 10–12 opakování; pauza 60–90 s.", "poporodni_poznamka": "Začni bez zátěže a jen v bezbolestném rozsahu. Při bolesti zad cvik přeruš a zvol vhodnější variantu po konzultaci.", "category": "Záda a ramena"}, {"id": 28, "number": "028", "title": "Bench Press", "english": "Barbell Bench Press", "typ": "Vícekloubový horizontální tlak; osa a rovná lavice", "anatomie": "Hlavní: velký prsní sval. Pomocně triceps a přední delty; stabilizují rotátorová manžeta, svaly lopatek a trup.", "biomechanika": "Horizontální addukce ramene a extenze lokte. Lopatky zůstávají stabilně opřené o lavici.", "vychozi_pozice": "Lehni si, chodidla pevně na zemi. Oči přibližně pod osou. Uchop osu symetricky, lopatky nastav stabilně na lavici, zápěstí drž přibližně nad lokty a předloktími.", "provedeni": "Spusť osu kontrolovaně k dolní až střední části hrudníku podle proporcí a úchopu. Předloktí zůstávají při pohledu zepředu přibližně svislá; lokty vedou v pohodlném úhlu. Vytlač osu vzhůru a mírně zpět nad ramenní kloub.", "spravna_technika": "Chodidla stabilní; zápěstí nad lokty; lopatky opřené; osa se pohybuje kontrolovaně; používej bezpečnostní dorazy nebo dopomoc.", "chyby": "Odskakování osy od hrudníku — zpomal. Zápěstí se láme — srovnej osu. Lokty extrémně do stran — uprav úhel. Ztráta stability — sniž váhu.", "dychani": "Nádech při spouštění, výdech při tlaku vzhůru. Zpevni trup a udrž stabilní oporu.", "varianty": "Regrese: chest press stroj nebo jednoručky s lehkou zátěží. Progrese: postupné přidávání váhy, pauza na hrudníku.", "davkovani": "3 série × 6–10 opakování; pauza 2 min.", "poporodni_poznamka": "Používej bezpečnostní dorazy či dopomoc. Při tlaku v pánvi nebo vyklenování břicha zvol lehčí zátěž či stroj.", "category": "Hrudník a paže"}, {"id": 29, "number": "029", "title": "Tlaky Jednoruček Na Rovné Lavici", "english": "Dumbbell Bench Press", "typ": "Vícekloubový horizontální tlak; jednoručky a lavice", "anatomie": "Hlavní: velký prsní sval. Pomocně triceps a přední delty; stabilizují svaly lopatek a rotátorová manžeta.", "biomechanika": "Horizontální addukce ramene a extenze lokte; každá paže stabilizuje vlastní zátěž.", "vychozi_pozice": "Lehni na rovnou lavici, chodidla na zemi. Jednoručky drž nad hrudníkem, zápěstí neutrální, lopatky stabilní.", "provedeni": "Spouštěj činky po stranách hrudníku do pohodlného rozsahu. Vytlač je vzhůru bez srážení a bez ztráty kontroly.", "spravna_technika": "Zápěstí nad lokty; lokty v pohodlném úhlu; ramena stabilní; pohyb symetrický; bez bolesti.", "chyby": "Činky se rozjíždějí — sniž váhu. Příliš hluboké spuštění — zkrať rozsah. Prohýbání beder — uprav oporu a zátěž.", "dychani": "Nádech při spouštění, výdech při tlaku.", "varianty": "Regrese: chest press stroj. Progrese: vyšší zátěž, pauza dole nebo střídavý tlak.", "davkovani": "3 série × 8–12 opakování; pauza 90–120 s.", "poporodni_poznamka": "Jednoručky vyžadují více stabilizace než stroj. Začni s vahou, kterou bezpečně dostaneš do výchozí pozice.", "category": "Hrudník a paže"}, {"id": 30, "number": "030", "title": "Tlaky Na Šikmé Lavici", "english": "Incline Dumbbell Press", "typ": "Vícekloubový tlak; šikmá lavice a jednoručky", "anatomie": "Hlavní: horní část velkého prsního svalu. Pomocně přední delty a triceps.", "biomechanika": "Horizontální addukce a flexe ramene, extenze lokte. Čím vyšší sklon, tím více se zapojují přední delty.", "vychozi_pozice": "Nastav lavici obvykle na mírný sklon. Opři záda a chodidla, činky drž nad horní částí hrudníku, lopatky stabilní.", "provedeni": "Spusť činky po stranách horní části hrudníku. Vytlač vzhůru v kontrolované dráze bez nárazu činek.", "spravna_technika": "Zápěstí nad lokty; ramena stabilní; nepřeháněj sklon; rozsah bez bolesti.", "chyby": "Příliš strmá lavice — sniž sklon. Činky se srážejí — drž dráhu. Záklon beder — sniž zátěž.", "dychani": "Nádech při spouštění, výdech při tlaku.", "varianty": "Regrese: chest press nebo menší sklon. Progrese: vyšší zátěž či pauza dole.", "davkovani": "3 série × 8–12 opakování; pauza 90 s.", "poporodni_poznamka": "Začni mírným sklonem a kontrolovanou zátěží; při nepohodlí ramene zvol rovnou lavici či stroj.", "category": "Hrudník a paže"}, {"id": 31, "number": "031", "title": "Tlak Na Hrudník Na Stroji", "english": "Machine Chest Press", "typ": "Vícekloubový horizontální tlak; stroj", "anatomie": "Hlavní: velký prsní sval. Pomocně triceps a přední delty.", "biomechanika": "Horizontální addukce ramene a extenze lokte. Stroj vede dráhu, ale nastavení sedadla je zásadní.", "vychozi_pozice": "Nastav sedadlo tak, aby madla byla přibližně ve výši středu hrudníku. Záda opřená, chodidla na zemi, zápěstí rovně.", "provedeni": "Vytlač madla vpřed bez zamčení loktů. Pomalu vrať do výchozí polohy, aniž by ramena ujížděla dopředu.", "spravna_technika": "Sedadlo správně nastavené; lopatky stabilní; zápěstí rovná; lokty v pohodlném úhlu; kontrolovaný návrat.", "chyby": "Sedadlo příliš nízko/vysoko — uprav polohu. Ramena se zvedají — sniž váhu. Náraz do dorazu — zpomal. Zkrácený návrat — použij bezpečný rozsah.", "dychani": "Výdech při tlaku, nádech při návratu.", "varianty": "Regrese: menší zátěž. Progrese: vyšší zátěž, pomalý návrat nebo jednostranná varianta, pokud ji stroj umožňuje.", "davkovani": "3 série × 8–12 opakování; pauza 60–90 s.", "poporodni_poznamka": "Stroj může být praktickou variantou při návratu k tlakům. Zátěž musí umožnit plynulé dýchání.", "category": "Hrudník a paže"}, {"id": 32, "number": "032", "title": "Rozpažování Na Kladkách", "english": "Cable Fly", "typ": "Jednokloubový cvik; dvě kladky", "anatomie": "Hlavní: velký prsní sval. Pomocně přední delty a stabilizátory ramene.", "biomechanika": "Horizontální addukce ramene s mírně pokrčeným loktem. Délka páky zvyšuje nárok na rameno.", "vychozi_pozice": "Nastav kladky přibližně do výšky ramen nebo podle cíle. Postav se do stabilního postoje, lokty lehce pokrčené, trup zpevněný.", "provedeni": "Veď paže obloukem před hrudník, jako bys objímala velký míč. Vrať pomalu do stran jen do rozsahu, který ramena snesou.", "spravna_technika": "Úhel loktů se výrazně nemění; ramena zůstávají dole; trup se nehoupá; kontrolovaný návrat.", "chyby": "Příliš hluboké protažení — zkrať rozsah. Ohýbání loktů jako při tlaku — udrž stejný úhel. Houpání — sniž zátěž.", "dychani": "Výdech při spojení paží, nádech při rozevírání.", "varianty": "Regrese: lehčí odpor nebo kratší rozsah. Progrese: pauza při spojení, změna výšky kladek.", "davkovani": "2–3 série × 10–15 opakování; pauza 60 s.", "poporodni_poznamka": "Začni s lehkým odporem, protože dlouhá páka zvyšuje nároky na ramena. Nechoď do bolestivého protažení.", "category": "Hrudník a paže"}, {"id": 33, "number": "033", "title": "Bicepsový Zdvih S Jednoručkami", "english": "Dumbbell Biceps Curl", "typ": "Jednokloubová izolace; jednoručky", "anatomie": "Hlavní: biceps brachii. Pomocně brachialis a brachioradialis.", "biomechanika": "Flexe lokte; při supinované variantě také supinace předloktí.", "vychozi_pozice": "Stůj nebo sedni vzpřímeně, paže podél těla, lokty blízko trupu, dlaně vpřed nebo v neutrální pozici pro střídavé provedení.", "provedeni": "Pokrč lokty a zvedni činky bez pohybu ramen. Pomalu spouštěj do téměř natažených loktů.", "spravna_technika": "Lokty zůstávají poblíž trupu; zápěstí rovná; trup bez švihu; plný pohodlný rozsah.", "chyby": "Houpání tělem — sniž zátěž. Lokty cestují vpřed — stabilizuj paže. Lámání zápěstí — drž je rovně. Příliš rychlý sestup — zpomal.", "dychani": "Výdech při zdvihu, nádech při spouštění.", "varianty": "Regrese: lehčí činky nebo střídavé zdvihy vsedě. Progrese: pomalý sestup, šikmá lavice nebo kladka.", "davkovani": "2–3 série × 10–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Snadno škálovatelný cvik. Nezvyšuj váhu, pokud musíš pomáhat trupem.", "category": "Hrudník a paže"}, {"id": 34, "number": "034", "title": "Kladivový Zdvih", "english": "Hammer Curl", "typ": "Jednokloubová izolace; jednoručky v neutrálním úchopu", "anatomie": "Hlavní: brachialis a brachioradialis; pomocně biceps brachii.", "biomechanika": "Flexe lokte při neutrálním postavení předloktí.", "vychozi_pozice": "Stůj vzpřímeně, činky podél těla, dlaně proti sobě. Lokty u trupu, zápěstí rovná.", "provedeni": "Zvedej činky směrem k ramenům bez otáčení dlaní. Pomalu spouštěj dolů.", "spravna_technika": "Neutrální úchop; lokty stabilní; trup bez švihu; kontrolovaný sestup.", "chyby": "Zvedání ramen — uvolni je. Švih — sniž váhu. Zápěstí se láme — drž rovně. Lokty ujíždějí — stabilizuj.", "dychani": "Výdech při zdvihu, nádech při spouštění.", "varianty": "Regrese: lehčí jednoručky. Progrese: střídavé zdvihy, kladka s lanem nebo pomalejší sestup.", "davkovani": "2–3 série × 10–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Při úchopu drž činku pevně, ale ne křečovitě. Přizpůsob váhu schopnosti kontrolovat zápěstí.", "category": "Hrudník a paže"}, {"id": 35, "number": "035", "title": "Tricepsové Stahování Kladky", "english": "Cable Triceps Pushdown", "typ": "Jednokloubová izolace; horní kladka s lanem nebo tyčí", "anatomie": "Hlavní: triceps brachii – všechny tři hlavy.", "biomechanika": "Extenze lokte; rameno zůstává převážně stabilní.", "vychozi_pozice": "Postav se čelem ke kladce, lokty u trupu, ramena uvolněná. Uchop madlo a mírně se předkloň jen pokud to pomáhá stabilitě.", "provedeni": "Natahuj lokty dolů, dokud paže nejsou téměř propnuté. Pomalu vrať předloktí vzhůru bez pohybu loktů vpřed a vzad.", "spravna_technika": "Lokty u těla; ramena dole; zápěstí neutrální; pohyb pouze v loktech; bez švihu.", "chyby": "Lokty se rozjíždějí — sniž váhu. Trup se houpe — stabilizuj postoj. Zápěstí se láme — srovnej úchop. Nedokončené propnutí — použij kontrolovaný rozsah.", "dychani": "Výdech při stlačení, nádech při návratu.", "varianty": "Regrese: lehčí kladka nebo guma. Progrese: lano, jednostranná varianta nebo pauza dole.", "davkovani": "2–3 série × 10–15 opakování; pauza 45–75 s.", "poporodni_poznamka": "Vhodný doplňkový cvik. Udržuj stabilní trup a dýchej plynule.", "category": "Hrudník a paže"}, {"id": 36, "number": "036", "title": "Tricepsová Extenze Nad Hlavou", "english": "Overhead Triceps Extension", "typ": "Jednokloubová izolace; jednoručka nebo kladka", "anatomie": "Hlavní: triceps brachii, zejména dlouhá hlava při paži nad hlavou.", "biomechanika": "Extenze lokte při rameni ve flexi; dlouhá hlava tricepsu je v protaženější poloze.", "vychozi_pozice": "Sedni nebo stůj stabilně. Zátěž drž nad hlavou, lokty směřují vpřed a zůstávají v pohodlné šířce. Žebra nad pánví.", "provedeni": "Pokrč lokty a spusť zátěž za hlavu do pohodlného rozsahu. Natahuj lokty vzhůru bez prohýbání beder.", "spravna_technika": "Lokty relativně stabilní; trup bez záklonu; zápěstí rovná; rozsah bez bolesti ramen a loktů.", "chyby": "Záklon — sniž zátěž nebo sedni. Lokty se nadměrně rozjíždějí — uprav šířku. Bolest ramene — zvol pushdown.", "dychani": "Nádech při pokrčení loktů, výdech při natažení.", "varianty": "Regrese: triceps pushdown. Progrese: jednoruční varianta nebo vyšší zátěž při stabilním trupu.", "davkovani": "2–3 série × 10–12 opakování; pauza 60 s.", "poporodni_poznamka": "Pokud poloha nad hlavou není pohodlná, není nutné ji vynucovat; použij stahování kladky.", "category": "Hrudník a paže"}, {"id": 37, "number": "037", "title": "Kliky", "english": "Push-up", "typ": "Vícekloubový horizontální tlak; vlastní váha", "anatomie": "Hlavní: prsní svaly. Pomocně triceps a přední delty; stabilizují břišní svaly, hýždě a svaly lopatek.", "biomechanika": "Horizontální addukce ramene a extenze lokte; trup drží prkno proti prohnutí.", "vychozi_pozice": "Dlaně o něco širší než ramena, prsty roztažené. Tělo v jedné linii od hlavy k patám; lopatky volně stabilní.", "provedeni": "Pokrč lokty a spusť hrudník směrem k podložce. Lokty směřují šikmo od trupu. Zatlač podlahu od sebe a vrať se vzhůru.", "spravna_technika": "Tělo jako celek; hlava v prodloužení páteře; lokty v pohodlném úhlu; lopatky se přirozeně pohybují; bez propadnutí beder.", "chyby": "Propadlá pánev — zvol vyšší oporu. Lokty příliš do stran — uprav úhel. Hlava padá — drž krk neutrálně. Nedostatečný rozsah — zvol lehčí variantu.", "dychani": "Nádech při klesání, výdech při vytlačení. Udržuj plynulé zpevnění trupu.", "varianty": "Regrese: kliky o stěnu, lavičku nebo na kolenou. Progrese: klasické kliky, pomalé tempo nebo zátěžová vesta.", "davkovani": "2–3 série × 6–12 opakování; pauza 60–90 s.", "poporodni_poznamka": "Po porodu začni kliky o vyvýšenou oporu. Sleduj vyklenování břišní stěny, tlak v pánvi či únik moči; při příznacích zvyš oporu nebo cvik uprav.", "category": "Hrudník a paže"}, {"id": 38, "number": "038", "title": "Mrtvý Brouk", "english": "Dead Bug", "typ": "Core – anti-extenze; podložka", "anatomie": "Hlavní: přímý a příčný břišní sval; pomocně šikmé břišní svaly. Stabilizují hluboké svaly trupu a pánevní dno koordinovaně s dechem.", "biomechanika": "Trup odolává extenzi a rotaci, zatímco kyčle a ramena se pohybují. Cílem není maximální přitlačení beder, ale kontrola polohy trupu.", "vychozi_pozice": "Lehni na záda, kyčle a kolena zvedni přibližně do pravého úhlu, paže nad rameny. Žebra nad pánví, dýchej plynule.", "provedeni": "Pomalu spouštěj protilehlou paži a nohu směrem k podlaze jen tak daleko, aby se trup neprohýbal a žebra nevystupovala. Vrať a vystřídej strany.", "spravna_technika": "Pomalý pohyb; pánev stabilní; žebra klidná; rozsah přizpůsobený kontrole; bez zadržování dechu.", "chyby": "Bedra se výrazně prohýbají — zkrať rozsah. Rychlé pohyby — zpomal. Zadržování dechu — zjednoduš variantu. Vyklenování břicha — zmenši páku.", "dychani": "Vydechuj při prodlužování končetin, nadechuj se při návratu. Výdech pomáhá koordinovat napětí trupu.", "varianty": "Regrese: střídavé dotyky patou o zem nebo pohyb jen paží/nohou. Progrese: delší páka, odporová guma nebo pomalejší tempo.", "davkovani": "2–3 série × 6–10 opakování na stranu; pauza 45–60 s.", "poporodni_poznamka": "Po porodu je důležitá kontrola břišní stěny a pánevního dna. Při vyklenování, tlaku, úniku moči či bolesti zmenši rozsah a konzultuj fyzioterapeutku.", "category": "Core a stabilita"}, {"id": 39, "number": "039", "title": "Pták–Pes", "english": "Bird Dog", "typ": "Core – antirotace a stabilita; podložka", "anatomie": "Stabilizují vzpřimovače páteře, příčný a šikmé břišní svaly; pohyb provádějí hýžďové svaly a svaly ramene.", "biomechanika": "Trup odolává rotaci a extenzi; kyčel se natahuje a rameno ohýbá při natažení protilehlých končetin.", "vychozi_pozice": "Klekni na všechny čtyři, ruce pod rameny, kolena pod kyčlemi. Páteř v přirozené poloze, hlava v prodloužení.", "provedeni": "Natahuje se protilehlá paže a noha do linie trupu. Pánev se neotáčí. Krátce podrž a vrať pod kontrolou; vystřídej strany.", "spravna_technika": "Pánev vodorovně; žebra nad pánví; končetiny nezdvihej výš než trup; bez rotace a švihu.", "chyby": "Zvedání nohy příliš vysoko — sniž ji. Rotace pánve — zkrať páku. Propadnutí mezi lopatkami — aktivně se opři o podložku. Zadržení dechu — zpomal.", "dychani": "Vydechni při natažení, nadechni se při návratu. Dýchej plynule během výdrže.", "varianty": "Regrese: natažení pouze nohy nebo paže, případně posun špičky po podlaze. Progrese: delší výdrž nebo lehký odpor.", "davkovani": "2–3 série × 6–10 opakování na stranu; pauza 45–60 s.", "poporodni_poznamka": "Vhodný nácvik koordinace. Pokud klek tlačí na břicho či pánev, použij jinou polohu.", "category": "Core a stabilita"}, {"id": 40, "number": "040", "title": "Pallof Press", "english": "Pallof Press", "typ": "Core – antirotace; kladka nebo odporová guma", "anatomie": "Šikmé a příčný břišní sval; stabilizují vzpřimovače páteře, hýždě a svaly kolem kyčlí.", "biomechanika": "Trup odolává rotaci vyvolané tahem gumy/kladky; ramena provádějí předpažení.", "vychozi_pozice": "Postav se bokem ke kladce, chodidla na šířku boků, madlo drž u hrudníku. Kolena měkce pokrčená, pánev a žebra nad sebou.", "provedeni": "S výdechem vytlač ruce před hrudník a odolávej tahu, který chce trup otočit. Krátce podrž a vrať ruce k hrudníku. Vystřídej strany.", "spravna_technika": "Pánev a hrudník míří vpřed; trup se neotáčí; ramena uvolněná; postoj stabilní; odpor zvládnutelný.", "chyby": "Rotace za madlem — sniž odpor. Záklon — srovnej žebra nad pánev. Zvedání ramen — uvolni je. Příliš široký postoj bez kontroly — uprav stabilitu.", "dychani": "Vydechuj při vytlačení, nadechuj při návratu; během výdrže dýchej.", "varianty": "Regrese: menší odpor a kratší výdrž. Progrese: delší paže, užší postoj nebo krokový Pallof press.", "davkovani": "2–3 série × 8–12 opakování na stranu nebo 10–20s výdrž; pauza 45–60 s.", "poporodni_poznamka": "Užitečný cvik pro kontrolu trupu. Zvol odpor, při kterém můžeš volně dýchat a nevzniká tlak v pánevním dnu.", "category": "Core a stabilita"}, {"id": 41, "number": "041", "title": "Prkno", "english": "Plank", "typ": "Core – anti-extenze; předloktí a špičky nebo vyvýšená opora", "anatomie": "Přímý, příčný a šikmé břišní svaly; stabilizují hýždě, kvadricepsy, ramenní pletenec a svaly páteře.", "biomechanika": "Trup odolává extenzi. Ramena a kyčle drží izometrickou pozici.", "vychozi_pozice": "Opři předloktí o zem, lokty pod rameny. Nohy natáhni, tělo v jedné linii; případně začni na kolenou nebo o lavičku.", "provedeni": "Zpevni trup a hýždě, dýchej plynule a drž polohu bez propadnutí beder či zvedání pánve. Ukonči sérii dřív, než se technika rozpadne.", "spravna_technika": "Lokty pod rameny; hlava v prodloužení; pánev stabilní; plynulý dech; krátká kvalitní výdrž je lepší než dlouhá s kompenzacemi.", "chyby": "Propadlá bedra — zvedni oporu nebo klekni. Příliš vysoko pánev — srovnej tělo. Zadržování dechu — zkrať výdrž. Třes a ztráta kontroly — ukonči sérii.", "dychani": "Dýchej plynule do žeber a břicha; nezadržuj dech. Udržuj přiměřené napětí, ne maximální zatnutí.", "varianty": "Regrese: plank o stěnu/lavičku nebo na kolenou. Progrese: delší páka či krátké kontrolované přenášení váhy.", "davkovani": "2–3 série × 10–30 sekund; pauza 45–60 s.", "poporodni_poznamka": "Po porodu začni variantou s vyšší oporou a postupuj podle tolerance. Vyklenování středové linie je signál upravit zátěž či techniku, nikoli samo o sobě diagnóza. Při přetrvávajícím tlaku/tíze v pánvi, úniku moči, bolesti nebo zhoršování příznaků vyhledej fyzioterapeutku pánevního dna či lékaře.", "category": "Core a stabilita"}, {"id": 42, "number": "042", "title": "Boční Prkno", "english": "Side Plank", "typ": "Core – anti-laterální flexe; předloktí a chodidla/kolena", "anatomie": "Šikmé břišní svaly a quadratus lumborum; stabilizují střední hýžďový sval, rameno a hluboké svaly trupu.", "biomechanika": "Trup odolává bočnímu ohnutí. Kyčle drží v izometrické pozici.", "vychozi_pozice": "Lehni na bok, loket pod ramenem. Kolena pokrčená pro lehčí variantu nebo nohy natažené pro náročnější. Ramena a pánev v jedné linii.", "provedeni": "Zvedni pánev od podložky a drž tělo v přímé linii. Dýchej plynule, poté kontrolovaně spusť.", "spravna_technika": "Loket pod ramenem; pánev nepadá; trup se neotáčí; krk uvolněný; výdrž bez bolesti ramene.", "chyby": "Rameno se hroutí — uprav oporu. Pánev padá — zkrať výdrž. Rotace trupu — zjednoduš variantu. Zadržování dechu — zkrať interval.", "dychani": "Plynule dýchej během výdrže; nezadržuj dech.", "varianty": "Regrese: boční plank na kolenou nebo o lavičku. Progrese: plná varianta, zvednutí horní nohy až při stabilitě.", "davkovani": "2–3 série × 10–25 sekund na stranu; pauza 45–60 s.", "poporodni_poznamka": "Začni na kolenou nebo o vyvýšenou oporu. Sleduj tlak v pánvi a schopnost volně dýchat.", "category": "Core a stabilita"}, {"id": 43, "number": "043", "title": "Most S Pochodováním", "english": "Glute Bridge March", "typ": "Core a hýždě; podložka", "anatomie": "Hýžďové svaly a hamstringy; stabilizují šikmé a příčné břišní svaly a svaly kolem pánve.", "biomechanika": "Kyčle drží extenzi, zatímco střídavé odlehčení nohou vytváří nárok na antirotaci a stabilitu pánve.", "vychozi_pozice": "Lehni na záda, pokrč kolena, chodidla na zemi. Zvedni pánev do mostu v rozsahu, kde udržíš žebra a pánev stabilní.", "provedeni": "Pomalu odlep jednu nohu jen několik centimetrů nebo zvedni koleno, aniž by pánev poklesla či rotovala. Polož a vystřídej.", "spravna_technika": "Pánev vodorovně; hýždě aktivní; minimální pohyb trupu; bez přehnutí beder.", "chyby": "Pánev se kýve — vrať se ke klasickému mostu. Zvedání nohy příliš vysoko — zmenši pohyb. Křeče hamstringů — uprav chodidla.", "dychani": "Vydechni při odlehčení nohy, nadechni se při položení; dech plynulý.", "varianty": "Regrese: statický glute bridge. Progrese: delší výdrž na jedné noze nebo miniband při zachované stabilitě.", "davkovani": "2 série × 6–10 střídání na stranu; pauza 45–60 s.", "poporodni_poznamka": "Zařaď až tehdy, když zvládáš běžný most bez příznaků a bez pohybu pánve. Při tlaku či vyklenování se vrať k lehčí variantě.", "category": "Core a stabilita"}, {"id": 44, "number": "044", "title": "Posouvání Paty", "english": "Heel Slides", "typ": "Core – kontrola trupu; podložka", "anatomie": "Příčný a přímý břišní sval, šikmé břišní svaly; koordinace s bránicí a pánevním dnem.", "biomechanika": "Kyčel a koleno se natahují a ohýbají, zatímco trup odolává pohybu pánve a extenzi beder.", "vychozi_pozice": "Lehni na záda, kolena pokrčená, chodidla na podložce. Žebra uvolněná, pánev v pohodlné neutrální poloze.", "provedeni": "Pomalu posuň jednu patu po podložce od těla, jen do vzdálenosti, kdy zůstává pánev stabilní a dech plynulý. Vrať a vystřídej.", "spravna_technika": "Pánev se nehýbe; žebra nevystupují; pohyb pomalý; bez zadržování dechu.", "chyby": "Bedra se prohýbají — zkrať posun. Pánev se otáčí — zpomal. Zadržení dechu — zmenši rozsah. Vyklenování břicha — vrať se k menšímu pohybu.", "dychani": "Vydechuj při posunu paty, nadechuj při návratu.", "varianty": "Regrese: krátký posun paty. Progrese: delší posun, střídavé zvednutí nohy nebo koordinace s pažemi.", "davkovani": "2–3 série × 8–10 opakování na stranu; pauza 30–45 s.", "poporodni_poznamka": "Jemná varianta pro nácvik koordinace břišní stěny a dechu. Při příznacích zmenši rozsah a konzultuj fyzioterapeutku.", "category": "Core a stabilita"}, {"id": 45, "number": "045", "title": "Sekání Dřeva Na Kladce", "english": "Cable Woodchop", "typ": "Vícekloubový rotační cvik; kladka", "anatomie": "Šikmé břišní svaly; pomocně přímý břišní sval, široký sval zádový, hýždě a svaly ramen.", "biomechanika": "Kontrolovaná rotace trupu a pohyb ramen/kyčlí podle varianty. Rotace má být rozložená, ne násilně v bedrech.", "vychozi_pozice": "Postav se bokem ke kladce, chodidla stabilní. Uchop madlo oběma rukama, kolena lehce pokrčená. Nastav odpor nízko.", "provedeni": "Veď ruce šikmo přes tělo podle nastavení kladky. Trup se otáčí kontrolovaně v rozsahu, který zvládneš bez bolesti; vrať pomalu. Pohyb může zahrnovat i kyčle a chodidla.", "spravna_technika": "Pohyb plynulý; pánev a chodidla se přizpůsobují variantě; bez trhání; ramena uvolněná.", "chyby": "Rotace pouze v bedrech — zmenši rozsah a dovol pohyb kyčlím/hrudníku. Švih — sniž odpor. Tah pažemi bez kontroly trupu — zpomal.", "dychani": "Vydechuj při tahu, nadechuj při návratu.", "varianty": "Regrese: Pallof press bez rotace. Progrese: vyšší odpor nebo poloklek, pouze pokud je rotace kontrolovaná.", "davkovani": "2–3 série × 8–12 opakování na stranu; pauza 60 s.", "poporodni_poznamka": "Po porodu postupuj podle tolerance a funkce, ne podle pevného časového limitu. Nejprve zvládni lehký odpor bez bolesti, tlaku v pánvi, úniku moči či ztráty kontroly trupu; dynamickou rotaci přidávej postupně.", "category": "Core a stabilita"}, {"id": 46, "number": "046", "title": "Farmářská Chůze", "english": "Farmer’s Carry", "typ": "Funkční přenášení zátěže; dvě jednoručky/kettlebell", "anatomie": "Úchop a předloktí; trapézy; stabilizují břišní svaly, vzpřimovače páteře, hýždě a svaly chodidel.", "biomechanika": "Trup odolává bočnímu náklonu a rotaci; lopatky a ramena stabilizují zátěž při chůzi.", "vychozi_pozice": "Zvedni dvě stejně těžké zátěže ze země bezpečným hip hinge/dřepem. Stůj vzpřímeně, paže podél těla, ramena přirozeně.", "provedeni": "Jdi krátkými kontrolovanými kroky. Udržuj trup vzpřímený, pohled vpřed a zátěž klidnou. Polož zátěž kontrolovaně.", "spravna_technika": "Žebra nad pánví; ramena bez přehnaného zvedání; kroky stabilní; bez naklánění; dýchej průběžně.", "chyby": "Příliš těžká váha — zkrať vzdálenost nebo sniž zátěž. Naklánění — vyrovnej zátěž. Zadržování dechu — zpomal. Hlučné dopady — zkrať krok.", "dychani": "Dýchej průběžně během chůze; neprováděj dlouhou výdrž se zadrženým dechem.", "varianty": "Regrese: lehčí zátěž, kratší vzdálenost nebo jednostranné držení s oporou. Progrese: delší vzdálenost, vyšší zátěž nebo suitcase carry.", "davkovani": "3 série × 20–40 m nebo 20–40 s; pauza 60–90 s.", "poporodni_poznamka": "Praktický přenos do nošení nákupů či dítěte. Začni lehce, dýchej a sleduj případnou tíhu v pánvi či únik moči.", "category": "Core a stabilita"}, {"id": 47, "number": "047", "title": "Zkracovačky S Podsazením Pánve", "english": "Reverse Crunch", "typ": "Core – flexe trupu/pánve; podložka", "anatomie": "Přímý břišní sval; pomocně šikmé břišní svaly. Flexory kyčle mohou pomáhat, pokud se pohyb provádí švihem.", "biomechanika": "Pánev se kontrolovaně odvaluje od podložky směrem k hrudníku; nejde o švih nohou.", "vychozi_pozice": "Lehni na záda, kyčle a kolena pokrčené, ruce podél těla. Začni malým rozsahem, žebra klidná.", "provedeni": "S výdechem jemně přibliž kolena k hrudníku a odlep kostrč/pánev o malý kousek od podložky. Pomalu vrať bez švihu.", "spravna_technika": "Pohyb malý a kontrolovaný; bez švihu; krk uvolněný; bedra se neodrážejí od země.", "chyby": "Švih nohou — zmenši rozsah. Tah kolen bez podsazení pánve — zpomal. Tlak do krku — uvolni hlavu. Vyklenování břicha — zjednoduš.", "dychani": "Výdech při podsazení pánve, nádech při návratu.", "varianty": "Regrese: heel slides nebo dead bug. Progrese: pomalejší excentrická fáze a větší kontrolovaný rozsah.", "davkovani": "2 série × 8–12 opakování; pauza 45–60 s.", "poporodni_poznamka": "Po porodu nezařazuj automaticky jen kvůli vzhledu břicha. Nejprve ověř toleranci flexe trupu a kontrolu břišní stěny; při vyklenování, tlaku či bolesti zvol regresi.", "category": "Core a stabilita"}, {"id": 48, "number": "048", "title": "Kettlebell Swing", "english": "Kettlebell Swing", "typ": "Balistický kyčelní tah; kettlebell", "anatomie": "Hlavní: hýžďové svaly a hamstringy. Pomocně adduktory; stabilizují široký sval zádový, břišní svaly a úchop.", "biomechanika": "Rychlá extenze kyčle; kolena se mírně ohýbají. Kettlebell je poháněn kyčlemi, nikoli zvedán pažemi.", "vychozi_pozice": "Začni s kettlebellem před sebou, chodidla na šířku boků. Proveď hip hinge, uchop madlo a nastav stabilní páteř. Nejdřív zvládni nácvik tahu.", "provedeni": "Pošli kettlebell mezi stehna a prudce, ale kontrolovaně propni kyčle. Nech kettlebell vystoupat přirozeně přibližně do výšky hrudníku. Vrať jej mezi stehna v hip hinge.", "spravna_technika": "Síla vychází z kyčlí; paže jsou háky; páteř stabilní; kettlebell blízko těla; rytmus plynulý.", "chyby": "Dřep místo hip hinge — nacvič tah. Zvedání pažemi — zaměř se na kyčle. Přehnutí zad — ukonči švih níže. Příliš těžká váha — sniž zátěž.", "dychani": "Výdech při prudké extenzi kyčlí, nádech při návratu; rytmické dýchání.", "varianty": "Regrese: kettlebell deadlift a nácvik hike pass. Progrese: vyšší zátěž či delší série až při zvládnuté technice.", "davkovani": "3 série × 8–15 opakování; pauza 90–120 s.", "poporodni_poznamka": "Balistický cvik není první volbou při návratu po porodu. Zařazuj až po zvládnutí hip hinge a silových základů bez příznaků, ideálně po odborném posouzení.", "category": "Komplexní cviky"}, {"id": 49, "number": "049", "title": "Tlačení Saní", "english": "Sled Push", "typ": "Komplexní lokomoční tlak; posilovací saně", "anatomie": "Kvadricepsy, hýžďové svaly a lýtka; stabilizují trup, ramena a paže.", "biomechanika": "Opakovaná extenze kyčlí, kolen a kotníků při posunu vpřed; trup odolává prohnutí.", "vychozi_pozice": "Uchop madla ve vhodné výšce, nakloň se z kotníků/kyčlí jako celek. Zpevni trup, chodidla na šířku boků.", "provedeni": "Tlač saně vpřed krátkými silnými kroky. Udržuj konstantní tlak do madel a plynulý rytmus. Zátěž zvol tak, abys neztrácela polohu.", "spravna_technika": "Trup stabilní; kroky kontrolované; kolena sledují chodidla; bez propadnutí beder; dýchání plynulé.", "chyby": "Příliš těžké saně — sniž zátěž. Zvedání ramen — uvolni je. Dlouhé nekontrolované kroky — zkrať krok. Zadržování dechu — zpomal.", "dychani": "Dýchej rytmicky během tlačení; výdech může doprovázet úsilí, nezadržuj dech dlouho.", "varianty": "Regrese: lehčí saně a kratší vzdálenost. Progrese: vyšší zátěž, delší úsek nebo rychlejší tempo.", "davkovani": "3–5 úseků × 10–20 m; pauza 60–120 s.", "poporodni_poznamka": "Náročnost může rychle stoupat. Začni lehce a sleduj tlak v pánevním dnu, únik moči a schopnost dýchat.", "category": "Komplexní cviky"}, {"id": 50, "number": "050", "title": "Dřep S Tlakem Nad Hlavu", "english": "Thruster", "typ": "Komplexní vícekloubový cvik; jednoručky nebo osa", "anatomie": "Kvadricepsy a hýžďové svaly při dřepu; delty a triceps při tlaku. Stabilizují trup, horní záda a svaly kyčlí.", "biomechanika": "Flexe a extenze kyčlí/kolen v dřepu, následně flexe/abdukce ramen a extenze loktů v tlaku. Přechod vyžaduje koordinaci.", "vychozi_pozice": "Zátěž drž u ramen, chodidla stabilně na šířku ramen. Zpevni trup, lokty v pohodlné pozici a žebra nad pánví.", "provedeni": "Proveď kontrolovaný dřep. Při vstávání plynule navazuj tlakem zátěže nad hlavu. Spusť zátěž zpět k ramenům a připrav další opakování.", "spravna_technika": "Dřep a tlak plynule navazují; kolena sledují špičky; trup bez záklonu; zátěž nad středem těla; dech koordinovaný.", "chyby": "Příliš těžká zátěž — rozděl cvik na dřep a tlak. Záklon při tlaku — sniž váhu. Kolena dovnitř — kontroluj postoj. Ztráta rytmu — zpomal.", "dychani": "Nádech a zpevnění před dřepem, výdech při vstávání a tlaku. Při vyšší zátěži obnov dech mezi opakováními.", "varianty": "Regrese: dřep s vlastní vahou a samostatný lehký tlak. Progrese: jednoručky, osa nebo plynulejší tempo při zvládnuté technice.", "davkovani": "2–3 série × 6–10 opakování; pauza 90–150 s.", "poporodni_poznamka": "Jde o náročný komplexní cvik. Zařazuj až po zvládnutí samostatného dřepu a tlaku bez příznaků; po porodu není nutné spěchat k dynamickým kombinacím. Redakční poznámka k použití atlasu Před tiskem/grafickým zpracováním doporučuji sjednotit názvosloví (např. „velký hýžďový sval“, „střední hýžďový sval“, „široký sval zádový“), používat český název jako hlavní a anglický název jako doplněk. U každé ilustrace vyznačuj primární svaly jednou barvou a sekundární/stabilizační svaly odlišnou barvou; barevné zvýraznění má být označeno jako orientační, nikoli jako přesné měření svalové aktivity.", "category": "Komplexní cviky"}];
const $ = s => document.querySelector(s);
const view = $("#view");
const store = {
 get(k, fallback){try{return JSON.parse(localStorage.getItem("fa_"+k)) ?? fallback}catch{return fallback}},
 set(k,v){localStorage.setItem("fa_"+k,JSON.stringify(v))}
};
let tab="home", activeExercise=null, activeFilter="Vše", searchTerm="", currentWorkout=null, timerInt=null, timerLeft=0;
const categories=["Vše","Nohy a hýždě","Záda a ramena","Hrudník a paže","Core a stabilita","Komplexní cviky"];
const sectionNames={typ:"Typ a vybavení",anatomie:"Anatomie",biomechanika:"Biomechanika",vychozi_pozice:"Výchozí pozice",provedeni:"Provedení",spravna_technika:"Správná technika",chyby:"Nejčastější chyby a opravy",dychani:"Dýchání a stabilizace",varianty:"Regrese a progrese",davkovani:"Orientační dávkování",poporodni_poznamka:"Poporodní poznámka"};
function toast(t){const el=$("#toast");el.textContent=t;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),1900)}
function art(seed=1){return `<svg viewBox="0 0 100 110" aria-hidden="true"><circle cx="51" cy="15" r="9" fill="#d4ddd5"/><path d="M42 27 Q50 22 59 27 L64 55 L58 61 L62 94 L51 99 L47 68 L42 99 L31 96 L38 60 L32 54Z" fill="#c2d1c5"/><path d="M42 30 L25 48 L17 72 L23 75 L38 55 M59 30 L75 48 L82 70 L76 73 L63 55" fill="none" stroke="#9aafa0" stroke-width="7" stroke-linecap="round"/><path d="${seed%3===0?'M37 60 Q50 67 62 60':seed%3===1?'M37 43 Q50 49 63 43':'M37 77 Q50 83 63 77'}" fill="none" stroke="#e66b4b" stroke-width="8" stroke-linecap="round"/><path d="M50 28 L50 59" stroke="#8ba493" stroke-width="2" stroke-linecap="round"/></svg>`}
function exerciseCard(e){return `<button class="exercise-card" data-ex="${e.id}"><div class="exercise-art">${art(e.id)}</div><div class="info"><b>${e.number} · ${e.title}</b><small>${e.english} · ${e.category}</small><span class="tag">Zobrazit techniku</span></div><span class="arrow">›</span></button>`}
function go(t){tab=t;activeExercise=null;document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.tab===t));render()}
function render(){
 if(activeExercise){renderDetail();return}
 if(tab==="home")renderHome(); else if(tab==="atlas")renderAtlas(); else if(tab==="training")renderTraining(); else renderProgress();
}
function renderHome(){
 const logs=store.get("logs",[]), fav=store.get("favs",[]);
 view.innerHTML=`<section class="hero"><span class="eyebrow">TVŮJ POHYB. TVOJE ZNALOSTI.</span><h1>Rozuměj každému opakování.</h1><p>Anatomie, technika a trénink na jednom místě. Tvůj osobní průvodce posilovnou.</p><div class="hero-row"><div class="hero-stat"><b>50</b><span>cviků v atlasu</span></div><div class="hero-stat"><b>${logs.length}</b><span>zapsaných sérií</span></div><div class="hero-stat"><b>${fav.length}</b><span>oblíbených</span></div></div></section>
 <div class="section-head"><h2>Rychlý přístup</h2></div><div class="quick-grid">
 <button class="quick-card" data-go="atlas"><span class="quick-icon">◉</span><b>Prozkoumat atlas</b><small>50 cviků a technika</small></button>
 <button class="quick-card" data-go="training"><span class="quick-icon">＋</span><b>Začít trénink</b><small>Zapisuj série a váhy</small></button>
 <button class="quick-card" data-go="progress"><span class="quick-icon">↗</span><b>Můj progres</b><small>Historie a statistiky</small></button>
 <button class="quick-card" data-go="atlas" data-filter="Oblíbené"><span class="quick-icon">♡</span><b>Oblíbené cviky</b><small>${fav.length} uložených cviků</small></button></div>
 <div class="section-head"><h2>Vhodné pro rychlé studium</h2><button data-go="atlas">Všechny cviky →</button></div>
 <div class="exercise-list">${[1,2,6,28].map(id=>exerciseCard(DATA.find(e=>e.id===id))).join("")}</div>`;
}
function renderAtlas(){
 const fav=store.get("favs",[]);
 let list=DATA.filter(e=>(activeFilter==="Vše"||e.category===activeFilter||(activeFilter==="Oblíbené"&&fav.includes(e.id))) && (`${e.title} ${e.english} ${e.category}`.toLowerCase().includes(searchTerm.toLowerCase())));
 view.innerHTML=`<h1 class="page-title">Anatomický atlas</h1><p class="subline">Najdi cvik podle názvu nebo svalové partie. Otevři detail a prostuduj techniku.</p><label class="search"><span>⌕</span><input id="searchInput" placeholder="Hledat cvik, sval nebo kategorii…" value="${searchTerm}"></label><div class="chips">${["Vše",...categories.slice(1),"Oblíbené"].map(c=>`<button class="chip ${activeFilter===c?'active':''}" data-filter="${c}">${c}</button>`).join("")}</div><div class="section-head"><h2>${list.length} cviků</h2><span class="subline">${activeFilter}</span></div><div class="exercise-list">${list.length?list.map(exerciseCard).join(""):'<div class="empty">Nic jsme nenašli. Zkus jiný název nebo kategorii.</div>'}</div>`;
 $("#searchInput").addEventListener("input",e=>{searchTerm=e.target.value;const pos=e.target.selectionStart;renderAtlas();$("#searchInput").focus();$("#searchInput").setSelectionRange(pos,pos)});
}
function renderDetail(){
 const e=DATA.find(x=>x.id===activeExercise);if(!e)return;
 const fav=store.get("favs",[]).includes(e.id);
 const sections=Object.entries(sectionNames).map(([k,label])=>e[k]?`<section class="content-card"><h3><i></i>${label}</h3><p>${e[k]}</p></section>`:"").join("");
 view.innerHTML=`<button class="back-btn" id="backAtlas">← Zpět do atlasu</button><div class="detail-hero"><div class="exercise-art">${art(e.id)}</div><span class="eyebrow">CVIK ${e.number} / 050</span><h1>${e.title}</h1><div class="eng">${e.english}</div><div class="detail-meta"><span>${e.category}</span><span>Studijní karta</span></div></div><button class="secondary-btn" id="favBtn">${fav?"♥ V oblíbených":"♡ Přidat do oblíbených"}</button><button class="primary-btn" id="addWorkout">＋ Přidat do tréninku</button>${sections}<p class="subline">Obsah je edukativní pomůcka. Konkrétní techniku a dávkování přizpůsob své kondici, zátěži a případným příznakům.</p>`;
 $("#backAtlas").onclick=()=>{activeExercise=null;tab="atlas";render()};
 $("#favBtn").onclick=()=>{let a=store.get("favs",[]);a=a.includes(e.id)?a.filter(x=>x!==e.id):[...a,e.id];store.set("favs",a);renderDetail();toast(a.includes(e.id)?"Přidáno do oblíbených":"Odebráno z oblíbených")};
 $("#addWorkout").onclick=()=>{let w=store.get("workout",[]);if(!w.includes(e.id))w.push(e.id);store.set("workout",w);toast("Cvik přidán do tréninku")};
}
function renderTraining(){
 const ids=store.get("workout",[]), logs=store.get("logs",[]);
 view.innerHTML=`<h1 class="page-title">Můj trénink</h1><p class="subline">Sestav si trénink z atlasu a zapisuj skutečně odcvičené série.</p><div class="training-panel"><span class="eyebrow">AKTUÁLNÍ TRÉNINK</span><h2>${ids.length?ids.length+" zařazených cviků":"Zatím bez cviků"}</h2><p>${ids.length?"Otevři cvik a zapiš váhu i opakování.":"Přidej cviky z atlasu, které chceš dnes cvičit."}</p></div><button class="primary-btn" id="browseAdd">＋ Přidat cviky z atlasu</button><div class="section-head"><h2>Plán dne</h2><button id="clearWorkout">Vymazat plán</button></div><div class="exercise-list">${ids.map(id=>{let e=DATA.find(x=>x.id===id);return `<div class="content-card"><h3>${e.number} · ${e.title}</h3><p>${e.davkovani||"Dávkování dle cíle a možností."}</p><div class="set-row"><input type="number" min="0" step=".5" placeholder="kg" aria-label="Váha" id="weight-${id}"><input type="number" min="1" placeholder="opak." aria-label="Opakování" id="reps-${id}"><button class="secondary-btn" data-log="${id}">Zapsat</button><button class="remove-set" data-remove="${id}">×</button></div></div>`}).join("")||'<div class="empty">Zatím tu nic není. Přidej cviky z anatomického atlasu.</div>'}</div><div class="section-head"><h2>Poslední záznamy</h2></div>${logs.slice(-5).reverse().map(l=>`<div class="content-card"><h3>${l.title}</h3><p>${l.weight} kg × ${l.reps} opakování · ${new Date(l.date).toLocaleDateString("cs-CZ")}</p></div>`).join("")||'<div class="empty">Po prvním zapsaném setu se tady objeví historie.</div>'}<div class="content-card"><h3>⏱ Časovač pauzy</h3><p id="timerDisplay" style="font:800 28px Manrope;color:#267a55;margin:8px 0">01:30</p><div style="display:flex;gap:8px"><button class="secondary-btn" data-timer="60">60 s</button><button class="secondary-btn" data-timer="90">90 s</button><button class="secondary-btn" data-timer="120">120 s</button><button class="secondary-btn" id="stopTimer">Stop</button></div></div>`;
 $("#browseAdd").onclick=()=>{go("atlas")};
 $("#clearWorkout").onclick=()=>{store.set("workout",[]);renderTraining();toast("Plán vymazán")};
 document.querySelectorAll("[data-remove]").forEach(b=>b.onclick=()=>{store.set("workout",ids.filter(x=>x!==+b.dataset.remove));renderTraining()});
 document.querySelectorAll("[data-log]").forEach(b=>b.onclick=()=>{let id=+b.dataset.log,e=DATA.find(x=>x.id===id),weight=+$("#weight-"+id).value,reps=+$("#reps-"+id).value;if(!reps||reps<1){toast("Doplň počet opakování");return}let a=store.get("logs",[]);a.push({id,title:e.title,weight:weight||0,reps,date:new Date().toISOString()});store.set("logs",a);toast("Série uložena")});
 document.querySelectorAll("[data-timer]").forEach(b=>b.onclick=()=>startTimer(+b.dataset.timer));
 $("#stopTimer").onclick=()=>{clearInterval(timerInt);timerLeft=0;$("#timerDisplay").textContent="00:00"};
}
function startTimer(sec){clearInterval(timerInt);timerLeft=sec;tick();timerInt=setInterval(()=>{timerLeft--;tick();if(timerLeft<=0){clearInterval(timerInt);toast("Pauza skončila")}},1000)}
function tick(){let el=$("#timerDisplay");if(el)el.textContent=String(Math.floor(timerLeft/60)).padStart(2,"0")+":"+String(timerLeft%60).padStart(2,"0")}
function renderProgress(){
 const logs=store.get("logs",[]),fav=store.get("favs",[]);
 const totalVolume=logs.reduce((s,l)=>s+(l.weight||0)*(l.reps||0),0);
 const uniq=new Set(logs.map(l=>l.id)).size;
 const byExercise={};logs.forEach(l=>{byExercise[l.title]=(byExercise[l.title]||0)+1});
 const top=Object.entries(byExercise).sort((a,b)=>b[1]-a[1]).slice(0,5);
 view.innerHTML=`<h1 class="page-title">Můj progres</h1><p class="subline">Přehled záznamů uložených v tomto zařízení.</p><div class="stats-grid"><div class="stat-card"><b>${logs.length}</b><span>zapsaných sérií</span></div><div class="stat-card"><b>${uniq}</b><span>procvičených cviků</span></div><div class="stat-card"><b>${Math.round(totalVolume).toLocaleString("cs-CZ")}</b><span>kg × opakování celkem</span></div><div class="stat-card"><b>${fav.length}</b><span>oblíbených cviků</span></div></div><div class="section-head"><h2>Nejčastěji zapisované cviky</h2></div>${top.length?top.map(([name,n])=>`<div class="content-card"><h3>${name}</h3><p>${n} zapsaných sérií</p></div>`).join(""):'<div class="empty">Zatím nemáš žádné záznamy. Začni v sekci Trénink.</div>'}<div class="section-head"><h2>Historie</h2></div>${logs.slice().reverse().map(l=>`<div class="content-card"><h3>${l.title}</h3><p>${l.weight} kg × ${l.reps} opakování · ${new Date(l.date).toLocaleString("cs-CZ")}</p></div>`).join("")||'<div class="empty">Historie se začne plnit po prvním tréninku.</div>'}<button class="secondary-btn" id="exportData">Exportovat moje záznamy (JSON)</button>`;
 $("#exportData").onclick=()=>{let blob=new Blob([JSON.stringify({logs,favs:fav,workout:store.get("workout",[])},null,2)],{type:"application/json"});let a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="fitness-atlas-zalohovani.json";a.click();URL.revokeObjectURL(a.href)};
}
document.addEventListener("click",e=>{
 const ex=e.target.closest("[data-ex]");if(ex){activeExercise=+ex.dataset.ex;render();window.scrollTo(0,0);return}
 const goBtn=e.target.closest("[data-go]");if(goBtn){if(goBtn.dataset.filter)activeFilter=goBtn.dataset.filter;go(goBtn.dataset.go);return}
 const f=e.target.closest("[data-filter]");if(f){activeFilter=f.dataset.filter;renderAtlas();return}
 const nav=e.target.closest("[data-tab]");if(nav){go(nav.dataset.tab);return}
});
$("#profileBtn").onclick=()=>{$("#modalRoot").innerHTML=`<div class="modal-backdrop" id="modalClose"><div class="modal"><h2>Nastavení a data</h2><p>První verze ukládá oblíbené cviky, tréninkový plán a záznamy lokálně v tomto prohlížeči. Data zůstávají v zařízení.</p><button class="secondary-btn" id="backup">Exportovat zálohu</button><p>Pro přenos mezi zařízeními bude v další fázi potřeba cloudová synchronizace.</p><button class="primary-btn" id="closeModal">Zavřít</button></div></div>`;$("#closeModal").onclick=()=>$("#modalRoot").innerHTML="";$("#modalClose").onclick=e=>{if(e.target.id==="modalClose")$("#modalRoot").innerHTML=""};$("#backup").onclick=()=>{let blob=new Blob([JSON.stringify({logs:store.get("logs",[]),favs:store.get("favs",[]),workout:store.get("workout",[])},null,2)],{type:"application/json"});let a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="fitness-atlas-zaloha.json";a.click()}};
render();
if("serviceWorker" in navigator && location.protocol.startsWith("http")) navigator.serviceWorker.register("./sw.js").catch(()=>{});
